/** Read-only acceptance: fictional entries, real immutable government sources.
 * Goldens are hand-calculated independently, never generated by this engine. */
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {loadEnvConfig} from '@next/env';
import {createServiceClient} from '../lib/supabase/service';
import {parseAudit,auditTable,suggestMapping} from '../app/api/audits/input';
import {defaultOptions,factDecisionSchema} from '../app/api/audits/model';
import {evaluateAuditEntry,summarizeAudit} from '../app/api/audits/engine';
import {selectReferenceIds,loadAuditReferences} from '../app/api/tariff/references/store';
import {exportAudit} from '../app/api/audits/store';
import {parseCsv} from '../lib/catalogue/csv';
loadEnvConfig(process.cwd());
async function main(){
 const dir='scripts/test-fixtures/historical-audits/',csv=await readFile(dir+'chapter99-entries.csv','utf8'),golden=JSON.parse(await readFile(dir+'chapter99-expected.json','utf8'));
 const entries=parseAudit(csv,suggestMapping(auditTable(csv).headers),{...defaultOptions,currencyUsd:true,dutiesOnly:true,ordinaryConsumption:true,standardCoverage:true});
 const db=createServiceClient(),ids=await selectReferenceIds(db,entries),refs=await loadAuditReferences(db,entries,ids),decisions=golden.decisions.map((d:unknown)=>factDecisionSchema.parse(d));
 const initial=entries.map((e,i)=>evaluateAuditEntry(e,[],'SYNTHETIC-PRODUCT',[],false,null,refs[i],true));
 const rows=entries.map((entry,i)=>({entry,result:evaluateAuditEntry(entry,[],'SYNTHETIC-PRODUCT',decisions,false,null,refs[i],true)}));
 assert.equal(entries.length,120);
 for(const [i,{entry,result}] of rows.entries()){
  const expected=golden.rows[i];assert.equal(entry.entry,expected.entry);
  assert.equal(initial[i].expected,expected.expected,`${entry.entry} initial: ${JSON.stringify(initial[i].findings)}`);
  assert.equal(initial[i].difference,expected.difference,entry.entry);
  assert.equal(result.expected,expected.reviewedExpected,`${entry.entry} reviewed: ${JSON.stringify(result.findings)}`);
  assert.equal(result.difference,expected.reviewedDifference,entry.entry);
  if(result.expected!==null)assert.equal(result.validation?.kind,'cante_validated');
 }
 const corrected=evaluateAuditEntry({...entries[0],paid:'290.00',chapter99:['9903.88.02']},[],'SYNTHETIC-PRODUCT',[{row:entries[0].row,kind:'confirm_facts',note:'SYNTHETIC reviewed legal-origin correction, not a supplier-address inference.',evidence:['SYNTHETIC-ORIGIN-DOC'],validFrom:'2024-02-15',validBefore:'2024-02-16',origin:'VN',facts:{origin_verified:true}}],false,null,refs[0],true);
 assert.equal(corrected.expected,'40.00');assert.equal(corrected.difference,'250.00');assert.equal(corrected.appliedOrigin,'VN');assert.equal(corrected.chapter99?.unresolved.length,0);assert(corrected.chapter99?.notApplicable?.some(x=>x.heading==='9903.88.02'));
 assert.deepEqual(summarizeAudit(initial),golden.summary);assert.deepEqual(summarizeAudit(rows.map(r=>r.result)),golden.reviewedSummary);
 const exported=parseCsv(exportAudit({batch:{id:'SYNTHETIC-CHAPTER99'},rows,decisions,verified:true,resultRevision:1}),undefined,true);
 assert.equal(exported.rows.length,120);
 exported.rows.forEach((r,i)=>{assert.equal(r.expected_duty_usd,golden.rows[i].reviewedExpected??'');assert.equal(r.paid_minus_expected_usd,golden.rows[i].reviewedDifference??'');assert.equal(r.declared_hts,entries[i].hts);assert.equal(r.calculation_exclusion,rows[i].result.appliedExclusion??'');assert.equal(r.exclusion_product_definition,rows[i].result.appliedExclusionScope??'');});
 console.log(JSON.stringify({source:'Real retained USITC/USTR/Presidential originals',declarations:'120 fictional entries',initial:summarizeAudit(initial),afterFictionalEvidenceReview:summarizeAudit(rows.map(r=>r.result)),reviewedOriginCorrection:{expected:corrected.expected,difference:corrected.difference,chinaHeadingNotApplicable:true},pinnedSources:ids.length,exportedRows:exported.rows.length,models:0,writes:0,legalApprovalsCreated:0,scope:'Bounded 2024 exclusions and China primary metal treatment, not universal Chapter 99 coverage.'}));
}
main().catch(error=>{console.error(error);process.exitCode=1;});
